            elif target_evader[1] < current_pos[1]:
                dy = -1
            return [dx, dy]

    # Priority 3: Territory control - move towards neutral territory
    if territory:
        # Find nearest neutral cell
        min_dist = float('inf')
        target_cell = None
        for idx, row in enumerate(territory):
            for jdx, cell in enumerate(row):
                if cell == 'neutral':
                    dist = abs(idx - current_pos[0]) + abs(jdx - current_pos[1])
